package com.steven.assets.bff.portfolioadvice;
import org.junit.jupiter.api.Test;import org.springframework.mock.http.server.reactive.MockServerHttpRequest;import org.springframework.mock.web.server.MockServerWebExchange;import com.steven.assets.bff.apierrorlogs.*;import reactor.core.publisher.Mono;import static org.mockito.Mockito.*;import static org.assertj.core.api.Assertions.*;
class SrppClaudeAuthPrivacyTest {
 @Test void authFailuresNeverEnterPublicApiIngestion(){var ingest=mock(ApiErrorLogIngestClient.class);var renderer=mock(ApiErrorLogDiagnosticRenderer.class);var filter=new PublicApiErrorCaptureWebFilter(ingest,renderer);for(String action:java.util.List.of("state","start","sessions/flow/complete","sessions/flow/cancel")){var ex=MockServerWebExchange.from(MockServerHttpRequest.post("/api/bff/portfolio-advice/srpp/ai-auth/claude/"+action));assertThatThrownBy(()->filter.filter(ex,e->Mono.error(new IllegalArgumentException("SECRET_CODE"))).block()).isInstanceOf(IllegalArgumentException.class);}verifyNoInteractions(ingest,renderer);}
 @Test void sameOriginRejectsMissingDuplicateUserinfoAndNonstandardPort(){assertThat(SrppClaudeAuthBffService.sameOrigin(MockServerWebExchange.from(MockServerHttpRequest.post("https://asset-management.asuscomm.com/path").header("Origin","https://asset-management.asuscomm.com")))).isTrue();for(String origin:java.util.List.of("https://u@asset-management.asuscomm.com","https://asset-management.asuscomm.com:444","https://asset-management.asuscomm.com?private=code"))assertThat(SrppClaudeAuthBffService.sameOrigin(MockServerWebExchange.from(MockServerHttpRequest.post("https://asset-management.asuscomm.com/path").header("Origin",origin)))).isFalse();}
 @Test void earlyNoStoreCoversSecurityAndBeforeHandlerErrorsOnlyForAuthPrefix(){var filter=new SrppClaudeAuthNoStoreWebFilter();for(int status:java.util.List.of(401,403,400,415,405,404)){var ex=MockServerWebExchange.from(MockServerHttpRequest.post("/api/bff/portfolio-advice/srpp/ai-auth/claude/start"));filter.filter(ex,e->{e.getResponse().setStatusCode(org.springframework.http.HttpStatusCode.valueOf(status));e.getResponse().getHeaders().set("Cache-Control","public");return e.getResponse().setComplete();}).block();assertThat(ex.getResponse().getHeaders().getCacheControl()).isEqualTo("no-store");}var other=MockServerWebExchange.from(MockServerHttpRequest.get("/api/bff/portfolio-advice/srpp"));filter.filter(other,e->e.getResponse().setComplete()).block();assertThat(other.getResponse().getHeaders().getCacheControl()).isNull();}
}
